CREATE LIVE VIEW 'energy_positions_live' FLUSH EVERY 5s IN MEMORY 5s PARTITION BY HOUR START FROM BEGINNING AS (
SELECT ts, book, symbol, curve,
                       sum(qty)      OVER w AS pos,
                       sum(qty * px) OVER w AS cost
                FROM energy_fills
                WINDOW w AS (PARTITION BY book, symbol ORDER BY ts ANCHOR DAILY '00:00')
);

<since_last_check>
  active_buffer: { id: 1, label: "SQL", kind: sql }
</since_last_check>

CREATE LIVE VIEW 'energy_positions_live_by_venue' FLUSH EVERY 5s IN MEMORY 5s PARTITION BY HOUR START FROM BEGINNING AS (
SELECT ts, book, symbol, curve, venue,
                       sum(qty)      OVER w AS pos,
                       sum(qty * px) OVER w AS cost
                FROM energy_fills
                WINDOW w AS (PARTITION BY book, symbol, venue ORDER BY ts ANCHOR DAILY '00:00')
);

<since_last_check>
