CREATE MATERIALIZED VIEW 'energy_curve_marks_1h' WITH BASE 'energy_curve_marks' REFRESH IMMEDIATE AS (
SELECT ts, curve, symbol, last(price) AS price
              FROM energy_curve_marks
              SAMPLE BY 1h
) PARTITION BY WEEK TTL 3 MONTHS;

