SELECT v.ts,v.symbol,v.delta_bucket,v.iv original_iv,c.iv corrected_iv,v.tau,v.iv*v.iv*v.tau original_var,c.iv*c.iv*c.tau corrected_var FROM energy_iv_marks v JOIN energy_iv_marks c ON v.ts=c.ts AND v.symbol=c.symbol AND v.delta_bucket=c.delta_bucket WHERE v.version=1 AND c.version=2;

WITH v AS (SELECT ts,curve,delta_bucket,symbol,tau,iv,iv*iv*tau variance FROM energy_iv_marks WHERE version=1), w AS (SELECT *,lag(variance) OVER (PARTITION BY ts,curve,delta_bucket ORDER BY tau) prev_var FROM v) SELECT curve,delta_bucket,count() n,sum(CASE WHEN variance<prev_var THEN 1 ELSE 0 END) calendar_inversions,min(variance-prev_var) min_step FROM w GROUP BY curve,delta_bucket;

WITH v AS (SELECT ts,curve,symbol,delta_bucket,tau,arg_max(iv,version) iv FROM energy_iv_marks GROUP BY ts,curve,symbol,delta_bucket,tau), w AS (SELECT *,iv*iv*tau variance,lag(iv*iv*tau) OVER (PARTITION BY ts,curve,delta_bucket ORDER BY tau) prev_var FROM v) SELECT curve,count() n,sum(CASE WHEN variance<prev_var THEN 1 ELSE 0 END) inversions FROM w GROUP BY curve

SELECT book,curve,count() n,sum(qty) qty FROM energy_trade_events WHERE version=1 AND trade_ts IN '2026-11-10' AND booked_ts IN '2026-11-11' GROUP BY book,curve ORDER BY book,curve;

WITH e AS (SELECT * FROM energy_trade_events WHERE booked_ts<='2026-11-11T23:59:59.999999' LATEST ON booked_ts PARTITION BY trade_id), moves AS (SELECT book,symbol,curve,qty FROM energy_position_snapshots WHERE ts IN '2026-11-11' UNION ALL SELECT book,symbol,curve,qty FROM e WHERE (trade_ts IN '2026-11-11' OR (trade_ts<'2026-11-11' AND booked_ts IN '2026-11-11')) AND status!='CANCELLED'), r AS (SELECT book,symbol,curve,sum(qty) qty FROM moves GROUP BY book,symbol,curve), a AS (SELECT book,symbol,curve,sum(qty) qty FROM energy_position_snapshots WHERE ts IN '2026-11-12' GROUP BY book,symbol,curve) SELECT count() n,max(abs(coalesce(r.qty,0)-coalesce(a.qty,0))) max_diff FROM r FULL OUTER JOIN a ON r.book=a.book AND r.symbol=a.symbol;

DECLARE @asof:='2026-11-11T23:59:59.999999'::timestamp SELECT 'known at close' object,channel,count() n FROM energy_book_asof GROUP BY channel UNION ALL SELECT 'restated' object,channel,count() n FROM energy_book_restated GROUP BY channel UNION ALL SELECT 'latest alias' object,channel,count() n FROM energy_trade_events_latest GROUP BY channel;

SELECT channel,count() session_trades,sum(CASE WHEN booked_ts IN '2026-11-12' THEN 1 ELSE 0 END) booked_next_day FROM energy_trade_events WHERE version=1 AND trade_ts IN '2026-11-11' GROUP BY channel

DECLARE @day:='2026-11-11'::timestamp WITH base AS (SELECT ts,book,symbol,sum(qty) OVER (PARTITION BY book,symbol ORDER BY ts) expected FROM energy_fills WHERE ts IN '2026-11-11') SELECT count() n,max(abs(b.expected-l.pos)) max_live_diff,max(abs(b.expected-d.pos)) max_day_diff FROM base b JOIN energy_positions_live l ON b.ts=l.ts AND b.book=l.book AND b.symbol=l.symbol JOIN energy_positions_running_day d ON b.ts=d.ts AND b.book=d.book AND b.symbol=d.symbol;

WITH base AS (SELECT ts,book,symbol,venue,sum(qty) OVER (PARTITION BY book,symbol,venue ORDER BY ts) expected FROM energy_fills WHERE ts IN '2026-11-11') SELECT count() n,max(abs(b.expected-l.pos)) max_diff FROM base b JOIN energy_positions_live_by_venue l ON b.ts=l.ts AND b.book=l.book AND b.symbol=l.symbol AND b.venue=l.venue;

SELECT src,count() n FROM energy_ledger WHERE ts IN '2026-11-11' GROUP BY src

WITH r AS (SELECT ts,symbol,last((bid+ask)/2) close,first((bid+ask)/2) open,max((bid+ask)/2) high,min((bid+ask)/2) low,count() ticks FROM energy_quotes WHERE ts IN '2026-11-11T08:40;15m' AND source IN ('CME','ICE','ICE_ENDEX','FX_FEED') SAMPLE BY 1m) SELECT count() n,max(abs(r.close-m.close)) close_diff,max(abs(r.open-m.open)) open_diff,max(abs(r.high-m.high)) high_diff,max(abs(r.low-m.low)) low_diff,max(abs(r.ticks-m.ticks)) ticks_diff FROM r JOIN energy_quotes_1m m ON r.ts=m.ts AND r.symbol=m.symbol;

WITH r AS (SELECT ts,symbol,last(close) close,max(high) high,min(low) low,first(open) open FROM energy_quotes_1m SAMPLE BY 5m), d AS (SELECT ts,symbol,last(close) close,max(high) high,min(low) low,first(open) open FROM energy_quotes_5m SAMPLE BY 1d) SELECT '5m' object,count() n,max(abs(r.close-m.close)) close_diff,max(abs(r.high-m.high)) high_diff,max(abs(r.low-m.low)) low_diff,max(abs(r.open-m.open)) open_diff FROM r JOIN energy_quotes_5m m ON r.ts=m.ts AND r.symbol=m.symbol UNION ALL SELECT '1d',count(),max(abs(d.close-m.close)),max(abs(d.high-m.high)),max(abs(d.low-m.low)),max(abs(d.open-m.open)) FROM d JOIN energy_quotes_1d m ON d.ts=m.ts AND d.symbol=m.symbol;

WITH r AS (SELECT ts,symbol,last(close) close,last(last_bid) last_bid,last(last_ask) last_ask FROM energy_quotes_10s SAMPLE BY 1m) SELECT count() n,max(abs(r.close-m.close)) close_diff,max(abs(r.last_bid-m.last_bid)) bid_diff,max(abs(r.last_ask-m.last_ask)) ask_diff FROM r JOIN energy_quotes_1m m ON r.ts=m.ts AND r.symbol=m.symbol;

